// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivateBank, Log} from "../src/PrivateBank.sol";

contract InvMutTest is Test {
    PrivateBank c;
    Recorder logRec;

    function setUp() public { 
        // deploy a recording Log replacement and pass its address into C
        logRec = new Recorder();
        c = new PrivateBank(address(logRec));
    }

    // Fuzzed parameters: actor (who will deposit and then cash out) and amount to deposit/cash
    function testFuzz_property(address actor, uint256 amount) public {
        // Keep actor non-zero and amount sensible
        vm.assume(actor != address(0));
        // bound amount to a reasonable range so vm.deal works and to include small and large values
        amount = bound(amount, 1 wei, 10 ether);

        // Give actor some Ether and make them deposit at least MinDeposit if we want to reach CashOut behavior
        uint256 minDep = c.MinDeposit();
        // Ensure we deposit at least MinDeposit so funds are recorded in balances in reference
        uint256 dep = amount < minDep ? minDep : amount;

        vm.deal(actor, dep);
        vm.startPrank(actor);
        // Deposit: this will call TransferLog.AddMessage on the reference; recorder will record it
        c.Deposit{value: dep}();
        vm.stopPrank();

        // Now attempt to CashOut some amount (fuzzed amount again; reuse `amount` but bound it to balance)
        uint256 bal = c.balances(actor);
        // If balance is zero we cannot cash out; choose cash amount in [0, bal]
        uint256 cash = bal == 0 ? 0 : bound(amount, 1 wei, bal);

        // If cash==0, calling CashOut with 0 is a no-op; we still exercise the call path when cash>0.
        bool ok;
        vm.deal(actor, 0); // ensure actor has no extra ETH except contract will send
        vm.startPrank(actor);
        try c.CashOut(cash) { ok = true; } catch { ok = false; }
        vm.stopPrank();

        // The general property we assert: if CashOut succeeded (ok==true) and cash>0,
        // the recorder MUST have observed an AddMessage call corresponding to the CashOut.
        // The reference contract makes that external call upon successful transfer; the mutant omits it.
        if (ok && cash > 0) {
            // recorder recorded calls to AddMessage; require at least one of them has matching fields
            // There may be previous Deposit log entries, so ensure that among recorded entries
            // there exists an entry with Sender==actor, Val==cash, and Data equals "CashOut".
            bool found = false;
            uint256 len = logRec.len();
            for (uint256 i = 0; i < len; i++) {
                (address s, uint256 v, string memory d) = logRec.get(i);
                if (s == actor && v == cash && keccak256(bytes(d)) == keccak256(bytes("CashOut"))) {
                    found = true;
                    break;
                }
            }
            assertTrue(found);
        } else {
            // if CashOut failed or cash==0, we cannot guarantee a CashOut log; but assertion must be single and read c
            // So assert a benign true by observing that balances remain consistent: balances(actor) equals previous bal minus (ok?cash:0)
            uint256 expected = bal;
            if (ok) { expected = bal - cash; }
            assertTrue(c.balances(actor) == expected);
        }
    }
}

// Recorder implements the Log interface used by C and records every AddMessage invocation.
contract Recorder {
    struct Entry { address sender; uint256 val; string data; }
    Entry[] public entries;

    // Matching signature to be called by C: AddMessage(address,uint256,string)
    function AddMessage(address _adr, uint256 _val, string memory _data) public {
        entries.push(Entry({ sender: _adr, val: _val, data: _data }));
    }

    // helpers for the test to read recorded entries
    function len() external view returns (uint256) { return entries.length; }
    function get(uint256 i) external view returns (address, uint256, string memory) {
        Entry storage e = entries[i];
        return (e.sender, e.val, e.data);
    }
}
